package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final ApplicationEventPublisher events;

    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows, Audit audit,
            ApplicationEventPublisher events) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
        this.events = events;
    }

    /** The sheet's holidays in date order. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add a holiday to the sheet, refused when the date is already one. Every due-by on or after it of
     *  a claim neither SETTLED nor VOID is then worked out again, past the holidays now. */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) throw alreadyHoliday(date);
        Holiday saved;
        try {
            saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        } catch (DataIntegrityViolationException raced) {
            throw alreadyHoliday(date);
        }
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + saved.getDate());
        events.publishEvent(new HolidaysChanged(sheetId, user, saved.getDate()));
        return saved;
    }

    /** The due-by of a claim fixed from the date with the terms: the terms-th business day after the
     *  date, skipping every Saturday, Sunday and holiday of the sheet now. */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
        return BusinessDays.after(date, terms, dates(sheetId));
    }

    /** The dates of the sheet's holidays now. */
    @Transactional(readOnly = true)
    public Set<LocalDate> dates(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
    }

    private static ResponseStatusException alreadyHoliday(LocalDate date) {
        return new ResponseStatusException(HttpStatus.CONFLICT, date + " is already a holiday.");
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/holidays")
@Validated
public class HolidayController {

    /** What the screen shows of a holiday: its date. */
    public record HolidayView(long id, LocalDate date) {
        static HolidayView of(Holiday holiday) {
            return new HolidayView(holiday.getId(), holiday.getDate());
        }
    }

    /** A holiday's date, as entered on the form. */
    public record HolidayForm(@NotNull LocalDate date) {
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    /** The sheet's holidays in date order. */
    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(HolidayView::of).toList();
    }

    /** Add a holiday to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public HolidayView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid HolidayForm form) {
        return HolidayView.of(service.add(sheetId.trim(), SignedInUser.name(user), form.date()));
    }
}
-- The sheet's holidays, each date at most once. A claim's due-by falling on one, when it is fixed,
-- moves to the next day that is not a holiday; due-by dates already fixed are kept as they are.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_once ON holiday (sheet_id, holiday_date);

