        if (termsFrom == null) fresh.setTerms(terms);
        else fresh.setTerms(terms, termsFrom);
        fresh.setContact(contactKey);
        List<String> tagged = ClaimService.tagsOf(tags);
        fresh.setTags(tagged);
        useTags(sheetId, tagged);
